def norm(s):
    s=unicodedata.normalize('NFKD',s.lower()); s=''.join(c for c in s if not unicodedata.combining(c)).replace('đ','d')
    return re.sub(r'[^a-z0-9 ]','',s).strip()
m=json.load(open(sys.argv[1]))
ex=set()
for k,v in m['cats'].items():
    for x in v: ex.add(norm(x['q']))
for t in m['tf']: ex.add(norm(t[0]))
for t in m['facts']: ex.add(norm(t))
out={}
for name,L in [("Drevne civilizacije",DC),("Povijest",P)]:
    res=[];seen=set()
    for i,(q,o) in enumerate(L):
        n=norm(q)
        if n in ex or n in seen: print('DUP',q); continue
        seen.add(n)
        assert len(o)==4 and len(set(o))==4,q
        if len(q)>110: print('LONGQ',len(q),q)
        for x in o:
            if len(x)>30: print('LONGO',x)
        a=len(res)%4; c=o[0]; rest=o[1:]; opts=rest[:a]+[c]+rest[a:]
        res.append({"q":q,"o":opts,"a":a})
    out[name]=res
json.dump({"cats":out},open(sys.argv[2],'w'),ensure_ascii=False,indent=1)
print({k:len(v) for k,v in out.items()})
